contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // single public entrypoint for property-based checking
    function run(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public payable {
        // No precondition on params: initialization may revert for AlreadyInitialized or FeeRateTooHigh.
        // We call initialize exactly once and observe public getters.

        // Read before-state that is observable
        bool beforeInitialized = c.initialized();

        // Attempt initialize and capture whether it reverted
        bool reverted;
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observable state after attempt
        bool afterInitialized = c.initialized();
        address baseToken = c.baseToken();
        address nft = c.nft();
        uint128 vb = c.virtualBaseTokenReserves();
        uint128 vn = c.virtualNftReserves();
        uint56 cf = c.changeFee();
        uint16 fr = c.feeRate();
        bytes32 mr = c.merkleRoot();
        bool uso = c.useStolenNftOracle();
        bool pr = c.payRoyalties();

        // The general rule to assert:
        // - If the call reverted, then the contract must remain in its previous initialized state (cannot flip from false->true on revert).
        // - If the call did not revert, then initialized must be true and all public fields must equal the supplied args.
        // This asserts a strong observable postcondition of initialize.
        assert(
            // If reverted: initialized unchanged (especially cannot become true if before was false)
            (reverted && afterInitialized == beforeInitialized)
            ||
            // If succeeded: initialized true and public getters match inputs
            (!reverted && afterInitialized
                && baseToken == _baseToken
                && nft == _nft
                && vb == _virtualBaseTokenReserves
                && vn == _virtualNftReserves
                && cf == _changeFee
                && fr == _feeRate
                && mr == _merkleRoot
                && uso == _useStolenNftOracle
                && pr == _payRoyalties)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take arrays and a MerkleMultiProof encoded as calldata-like memory by passing the components.
    // amountEth is used if baseToken==address(0) to pay msg.value to buy.
    function run(uint256[] memory tokenIds, uint256[] memory tokenWeights, bytes32[] memory proofProof, bool[] memory proofFlags, uint256 amountEth) public payable {
        // prepare MerkleMultiProof struct in memory
        C.MerkleMultiProof memory proof = C.MerkleMultiProof({ proof: proofProof, flags: proofFlags });

        // read before-values (observable)
        uint128 beforeVirtualNftReserves = c.virtualNftReserves();
        uint128 beforeVirtualBaseTokenReserves = c.virtualBaseTokenReserves();

        // compute expected quoted amounts for the weight sum (call view)
        // sum weights as the contract would
        uint256 weightSum = 0;
        for (uint256 i = 0; i < tokenWeights.length; i++) {
            weightSum += tokenWeights[i];
        }

        (uint256 netInputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.buyQuote(weightSum);

        // Ensure we have enough ETH if pool uses native token
        if (c.baseToken() == address(0)) {
            require(address(this).balance >= amountEth, "insufficient balance for ETH transfer");
        } else {
            // For ERC20 baseToken we don't send ETH; ensure amountEth is zero to avoid accidental misuse
            require(amountEth == 0, "amountEth must be zero when baseToken is ERC20");
        }

        // Attempt the buy; capture whether it reverted
        bool reverted;
        try c.buy{value: amountEth}(tokenIds, tokenWeights, proof) returns (uint256 returnedNetInput, uint256 returnedFee, uint256 returnedProtocolFee) {
            reverted = false;
            // returned values should equal the buyQuote computed earlier when not reverting
            // but we won't assert equality here; we will use them in the invariant check below
            netInputAmount = returnedNetInput;
            feeAmount = returnedFee;
            protocolFeeAmount = returnedProtocolFee;
        } catch {
            reverted = true;
        }

        // read after-values
        uint128 afterVirtualNftReserves = c.virtualNftReserves();
        uint128 afterVirtualBaseTokenReserves = c.virtualBaseTokenReserves();

        // If the call reverted, reserves must be unchanged; if it didn't, virtualNftReserves must have decreased by weightSum
        // and virtualBaseTokenReserves must have increased by (netInputAmount - feeAmount - protocolFeeAmount).
        // Express as a single assert over observed values and reverted flag.
        assert(
            (reverted && afterVirtualNftReserves == beforeVirtualNftReserves && afterVirtualBaseTokenReserves == beforeVirtualBaseTokenReserves)
            ||
            (!reverted && afterVirtualNftReserves + uint128(weightSum) == beforeVirtualNftReserves && afterVirtualBaseTokenReserves == beforeVirtualBaseTokenReserves + SafeCastTo128(netInputAmount - feeAmount - protocolFeeAmount))
        );
    }

    // helper to safely cast a uint256 delta to uint128 for the assert without relying on external libs
    function SafeCastTo128(uint256 x) internal pure returns (uint128) {
        require(x <= type(uint128).max, "cast overflow");
        return uint128(x);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take arrays and a MerkleMultiProof encoded as memory by passing the components.
    // amountEth is used if baseToken==address(0) to pay msg.value to buy.
    function run(uint256[] memory tokenIds, uint256[] memory tokenWeights, bytes32[] memory proofProof, bool[] memory proofFlags, uint256 amountEth) public payable {
        // Precondition: tokenIds and tokenWeights must be same length (as callers would do)
        require(tokenIds.length == tokenWeights.length, "length mismatch");

        // Build the MerkleMultiProof struct expected by the contract
        C.MerkleMultiProof memory proof = C.MerkleMultiProof({ proof: proofProof, flags: proofFlags });

        // Observe before-values (only through public getters)
        uint128 beforeVirtualNftReserves = c.virtualNftReserves();
        uint128 beforeVirtualBaseTokenReserves = c.virtualBaseTokenReserves();

        // Compute weightSum like the contract's sumWeightsAndValidateProof would (without merkle verification)
        uint256 weightSum = 0;
        for (uint256 i = 0; i < tokenWeights.length; i++) {
            weightSum += tokenWeights[i];
        }

        // Query the buyQuote for the computed weightSum (view call)
        (uint256 quotedNetInputAmount, uint256 quotedFeeAmount, uint256 quotedProtocolFeeAmount) = c.buyQuote(weightSum);

        // Ensure we have the ETH to forward if pool uses native token
        if (c.baseToken() == address(0)) {
            require(address(this).balance >= amountEth, "insufficient balance for ETH transfer");
        } else {
            // For ERC20 baseToken we don't intend to send ETH
            require(amountEth == 0, "amountEth must be zero when baseToken is ERC20");
        }

        // Attempt the state-changing buy call as a top-level statement and capture whether it reverted.
        bool reverted;
        uint256 returnedNetInput;
        uint256 returnedFee;
        uint256 returnedProtocolFee;
        try c.buy{value: amountEth}(tokenIds, tokenWeights, proof) returns (uint256 netIn, uint256 fee, uint256 protocolFee) {
            reverted = false;
            returnedNetInput = netIn;
            returnedFee = fee;
            returnedProtocolFee = protocolFee;
        } catch {
            reverted = true;
        }

        // Observe after-values
        uint128 afterVirtualNftReserves = c.virtualNftReserves();
        uint128 afterVirtualBaseTokenReserves = c.virtualBaseTokenReserves();

        // If the call reverted, reserves must be unchanged.
        // If it didn't revert, virtualNftReserves must have decreased by exactly weightSum,
        // and virtualBaseTokenReserves must have increased by (netInput - fee - protocolFee) as returned by the successful call.
        // Use the quoted values if call reverted (still required to form a general relation using observable results).

        assert(
            (reverted && afterVirtualNftReserves == beforeVirtualNftReserves && afterVirtualBaseTokenReserves == beforeVirtualBaseTokenReserves)
            ||
            (!reverted && afterVirtualNftReserves + uint128(weightSum) == beforeVirtualNftReserves && afterVirtualBaseTokenReserves == beforeVirtualBaseTokenReserves + (_safeCast128(returnedNetInput - returnedFee - returnedProtocolFee)))
        );
    }

    // helper to safely cast a uint256 delta to uint128 for the assert without using external libs
    function _safeCast128(uint256 x) internal pure returns (uint128) {
        require(x <= type(uint128).max, "cast overflow");
        return uint128(x);
    }

    receive() external payable {}
}

