        uint128 afterVirtualNftReserves = c.virtualNftReserves();
        uint128 afterVirtualBaseTokenReserves = c.virtualBaseTokenReserves();

        // Single general assertion: either revert leaves reserves unchanged, or successful return implies the exact reserve changes.
        // Avoid underflow by using addition for the nft reserve check and by requiring the net delta fits in uint128 when asserting base token reserves.
        bool successCase = !reverted
            && afterVirtualNftReserves + uint128(weightSum) == beforeVirtualNftReserves
            && returnedNetInput >= returnedFee + returnedProtocolFee
            && uint256(afterVirtualBaseTokenReserves) == uint256(beforeVirtualBaseTokenReserves) + (returnedNetInput - returnedFee - returnedProtocolFee);

