contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test deposit(tokenIds, baseTokenAmount) behavior. If pool uses ERC20 baseToken, msg.value must be 0.
    function run(uint256[] calldata tokenIds, uint256 baseTokenAmount, uint256 amountEth) public payable {
        require(tokenIds.length <= 10, "too many tokens"); // bound for verification
        // if pool expects ERC20, we must not send ETH; if pool expects native, amountEth is forwarded and must fit balance
        if (c.baseToken() == address(0)) {
            require(address(this).balance >= amountEth, "insufficient balance to forward ETH");
        } else {
            require(amountEth == 0, "must not send ETH when baseToken is ERC20");
        }

        // Observe before balances via public surface
        uint256 beforeNftBalance = ERC721(c.nft()).balanceOf(address(c));
        uint256 beforeBaseBalance = (c.baseToken() == address(0)) ? address(c).balance : ERC20(c.baseToken()).balanceOf(address(c));

        // perform deposit as top-level statement and capture revert
        bool reverted;
        try c.deposit{value: amountEth}(tokenIds, baseTokenAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after balances
        uint256 afterNftBalance = ERC721(c.nft()).balanceOf(address(c));
        uint256 afterBaseBalance = (c.baseToken() == address(0)) ? address(c).balance : ERC20(c.baseToken()).balanceOf(address(c));

        // Compute expected changes: on success, nft balance increases by tokenIds.length, base balance increases by baseTokenAmount (or amountEth when native)
        uint256 expectedBaseIncrease = (c.baseToken() == address(0)) ? amountEth : baseTokenAmount;
        bool successCase = !reverted
            && afterNftBalance == beforeNftBalance + tokenIds.length
            && afterBaseBalance == beforeBaseBalance + expectedBaseIncrease;

        bool revertCase = reverted
            && afterNftBalance == beforeNftBalance
            && afterBaseBalance == beforeBaseBalance;

        assert(successCase || revertCase);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test that calling buy with some tokenIds either reverts or results in those tokenIds being owned by the caller (msg.sender == address(this) for calls from this test contract),
    // and that virtualBaseTokenReserves increases by at least the netInputAmount - feeAmount - protocolFeeAmount (as observed through buyQuote),
    // and that when baseToken == address(0) Ether accounting to factory and caller is consistent with protocolFeeAmount and netInputAmount.
    function run(uint256[] calldata tokenIds, uint256[] calldata tokenWeights, bytes32[] calldata proof, bool[] calldata flags, uint256 ethSent) public payable {
        // Prepare MerkleMultiProof calldata struct
        C.MerkleMultiProof memory mp;
        mp.proof = proof;
        mp.flags = flags;

        // Ensure we have sufficient balance to send ETH if requested
        if (ethSent > 0) {
            require(address(this).balance >= ethSent);
        }

        // Read observable before-values
        uint128 beforeVirtualBase = c.virtualBaseTokenReserves();
        uint128 beforeVirtualNft = c.virtualNftReserves();
        address base = c.baseToken();
        address factory = c.factory();
        uint256 factoryBefore = address(factory).balance;
        uint256 poolBefore = address(c).balance;

        // Compute expected quote for the sum of weights (call view functions only)
        // sum weights: if merkleRoot==0 the contract will treat each token as 1e18
        uint256 weightSum;
        bytes32 merkleRoot = c.merkleRoot();
        if (merkleRoot == bytes32(0)) {
            weightSum = tokenIds.length * 1e18;
        } else {
            // If merkle root non-zero we cannot construct a valid proof generically; still compute weightSum from provided weights
            // but the buy call may revert due invalid proof; that's acceptable for the property.
            for (uint256 i = 0; i < tokenWeights.length; i++) weightSum += tokenWeights[i];
        }

        // Query quote for that output amount (view)
        (uint256 netInputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.buyQuote(weightSum);

        // Make the buy call, sending ETH if base token is ETH
        bool reverted = false;
        // Use try/catch to capture revert without bubbling
        try c.buy{value: (base == address(0) ? ethSent : 0)}(tokenIds, tokenWeights, mp) returns (uint256 a, uint256 b, uint256 d) {
            reverted = false;
            // values returned are captured in a,b,d but we don't rely on them beyond consistency
        } catch {
            reverted = true;
        }

        // After-values we can observe
        uint128 afterVirtualBase = c.virtualBaseTokenReserves();
        uint128 afterVirtualNft = c.virtualNftReserves();
        uint256 factoryAfter = address(factory).balance;
        uint256 poolAfter = address(c).balance;

        // For ownership checks, ownerOf may revert if token not minted; wrap attempts
        bool allTransferred = true;
        for (uint256 i = 0; i < tokenIds.length; i++) {
            // try to read owner; if reading reverts treat as not all transferred
            try ERC721(address(c.nft())).ownerOf(tokenIds[i]) returns (address owner) {
                if (owner != address(this)) {
                    allTransferred = false;
                }
            } catch {
                allTransferred = false;
            }
        }

        // Now assert the invariant: either the call reverted, or if it succeeded then:
        // 1) all specified tokenIds are owned by this contract (we are msg.sender for calls to c)
        // 2) virtualBaseTokenReserves increased by at least (netInputAmount - feeAmount - protocolFeeAmount) as that amount should be added to virtualBaseTokenReserves in buy
        // 3) virtualNftReserves decreased by exactly weightSum
        // 4) If base==address(0) then factory received protocolFeeAmount (factoryAfter >= factoryBefore + protocolFeeAmount) and pool Ether balance increased by netInputAmount (ignoring immediate royalty transfers)

        assert(
            reverted || (
                allTransferred &&
                // check virtual base reserves increase (use >= to be robust to royalty additions which add to netInput before transfer)
                uint256(afterVirtualBase) >= uint256(beforeVirtualBase) + (netInputAmount > feeAmount + protocolFeeAmount ? (netInputAmount - feeAmount - protocolFeeAmount) - 0 : 0) &&
                // virtual NFT reserves should decrease by weightSum when buy succeeds
                uint256(beforeVirtualNft) >= uint256(afterVirtualNft) && uint256(beforeVirtualNft) - uint256(afterVirtualNft) == weightSum &&
                (
                    base != address(0) || // if not ETH base, skip Ether accounting
                    (factoryAfter >= factoryBefore + protocolFeeAmount && poolAfter >= poolBefore + netInputAmount - protocolFeeAmount)
                )
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test that for any inputs, either buy reverts, or it succeeds and (1) each tokenId is transferred to the caller (this contract)
    // and (2) virtualNftReserves decreases by exactly the sum of tokenWeights (or by tokenIds.length*1e18 when merkleRoot==0).
    function run(uint256[] calldata tokenIds, uint256[] calldata tokenWeights, bytes32[] calldata proof, bool[] calldata flags, uint256 ethSent) public payable {
        // Precondition: lengths must match for token arrays to be meaningful for the call interface
        require(tokenIds.length == tokenWeights.length, "len");

        // Prepare MerkleMultiProof calldata struct
        C.MerkleMultiProof memory mp;
        mp.proof = proof;
        mp.flags = flags;

        // If we plan to send ETH, ensure test contract has balance for it
        if (ethSent > 0) {
            require(address(this).balance >= ethSent, "funds");
        }

        // Observe before-values
        uint128 beforeVirtualNft = c.virtualNftReserves();
        address poolNft = c.nft();

        // Perform the state-changing call as a top-level statement and capture whether it reverted
        bool reverted;
        try c.buy{value: (c.baseToken() == address(0) ? ethSent : 0)}(tokenIds, tokenWeights, mp) returns (uint256 /*netInput*/, uint256 /*fee*/, uint256 /*protocol*/) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after-values
        uint128 afterVirtualNft = c.virtualNftReserves();

        // Compute expected weight sum as the contract would: if merkleRoot == 0 then each token has weight 1e18
        uint256 expectedWeightSum = 0;
        bytes32 mr = c.merkleRoot();
        if (mr == bytes32(0)) {
            expectedWeightSum = tokenIds.length * 1e18;
        } else {
            for (uint256 i = 0; i < tokenWeights.length; i++) {
                expectedWeightSum += tokenWeights[i];
            }
        }

        // Check ownership: if the call succeeded then each tokenId must now be owned by this contract (the caller)
        bool allOwnedByCaller = true;
        if (!reverted) {
            for (uint256 i = 0; i < tokenIds.length; i++) {
                // ownerOf may revert for unknown tokens; in that case the buy should have reverted earlier, so treat as failure
                try ERC721(poolNft).ownerOf(tokenIds[i]) returns (address owner) {
                    if (owner != address(this)) {
                        allOwnedByCaller = false;
                    }
                } catch {
                    allOwnedByCaller = false;
                }
            }
        }

        // Final assertion: either buy reverted, or it succeeded and both conditions hold:
        // - every provided tokenId is owned by this contract
        // - virtualNftReserves decreased exactly by expectedWeightSum
        assert(
            reverted || (
                allOwnedByCaller &&
                // ensure no underflow in comparison by casting to uint256
                uint256(beforeVirtualNft) >= uint256(afterVirtualNft) &&
                uint256(beforeVirtualNft) - uint256(afterVirtualNft) == expectedWeightSum
            )
        );
    }

    // receive allows this test contract to hold ETH for buy calls
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Tests that deposit(tokenIds, baseTokenAmount) either reverts, or transfers all tokenIds into the pool
    // and increases the observable pool funds by at least baseTokenAmount (for ERC20 token: ERC20(baseToken).balanceOf(address(c));
    // for ETH: address(c).balance).
    function run(uint256[] calldata tokenIds, uint256 baseTokenAmount, uint256 ethToSend) public payable {
        // lengths are fine by calldata
        // If we plan to send ETH, ensure this contract has balance
        if (ethToSend > 0) { require(address(this).balance >= ethToSend, "funds"); }

        // Observe before-values
        address poolNft = c.nft();
        address poolBase = c.baseToken();
        uint256 beforePoolBalance;
        if (poolBase == address(0)) {
            beforePoolBalance = address(c).balance;
        } else {
            beforePoolBalance = ERC20(poolBase).balanceOf(address(c));
        }

        // Perform the state-changing call as a top-level statement and capture whether it reverted
        bool reverted;
        try c.deposit{value: (poolBase == address(0) ? ethToSend : 0)}(tokenIds, baseTokenAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after-values
        uint256 afterPoolBalance;
        if (poolBase == address(0)) {
            afterPoolBalance = address(c).balance;
        } else {
            afterPoolBalance = ERC20(poolBase).balanceOf(address(c));
        }

        // If deposit succeeded, each tokenId must now be owned by the pool (address(c)). If it reverted, we don't require ownership change.
        bool allOwnedByPool = true;
        if (!reverted) {
            for (uint256 i = 0; i < tokenIds.length; i++) {
                // ownerOf is a public view; if it reverts unexpectedly treat as not owned
                try ERC721(poolNft).ownerOf(tokenIds[i]) returns (address owner) {
                    if (owner != address(c)) {
                        allOwnedByPool = false;
                    }
                } catch {
                    allOwnedByPool = false;
                }
            }
        }

        // The general invariant: either the call reverted, or (a) all tokenIds are now owned by the pool and
        // (b) the observable pool funds increased by at least baseTokenAmount (for ETH it's address(c).balance).
        // Use >= to allow extra deposits or fees; cast to uint256 to avoid underflow.
        assert(
            reverted || (
                allOwnedByPool &&
                afterPoolBalance >= beforePoolBalance + baseTokenAmount
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Tests that deposit(tokenIds, baseTokenAmount) either reverts, or transfers all tokenIds into the pool
