            bool[] memory f = new bool[](0);
            proof = C.MerkleMultiProof({proof: p, flags: f});
        } else {
            // If caller provided some bytes we still treat it as empty (the property must hold for any inputs; checking both success and revert cases)
            bytes32[] memory p = new bytes32[](0);
            bool[] memory f = new bool[](0);
            proof = C.MerkleMultiProof({proof: p, flags: f});
        }

        // Prepare to call buy; must send Ether only if pool uses ETH (baseToken == address(0))
