            try c.buy(tokenIds, tokenWeights, mp) returns (uint256 n, uint256 f, uint256 p) {
                didRevert = false;
                netInputAmount = n; feeAmount = f; protocolFeeAmount = p;
            } catch {
                didRevert = true;
            }
        }

        // read after-values
        uint128 afterVirtualNft = c.virtualNftReserves();
        uint128 afterVirtualBase = c.virtualBaseTokenReserves();
        uint256 afterBalanceC = address(c).balance;

        // single general assert combining both revert and success cases
        assert(
            // If reverted: virtual reserves unchanged and balances unchanged
            (didRevert && afterVirtualNft == beforeVirtualNft && afterVirtualBase == beforeVirtualBase && afterBalanceC == beforeBalanceC)
            ||
            // If succeeded: reserves change matches expectations and ETH movement matches base token type
            (!didRevert
                && uint256(beforeVirtualNft) >= weightSum // avoid underflow possibility
                && uint256(beforeVirtualNft) - weightSum == uint256(afterVirtualNft)
                && uint256(afterVirtualBase) >= uint256(beforeVirtualBase)
                && uint256(afterVirtualBase) - uint256(beforeVirtualBase) == (netInputAmount - feeAmount - protocolFeeAmount)
                && ((base == address(0) && afterBalanceC == beforeBalanceC + netInputAmount) || (base != address(0) && afterBalanceC == beforeBalanceC))
            )
        );
    }

    receive() external payable {}
}

