            ||
            (!didRevert
                && retNetInput == qNetInput
                && retFee == qFee
                && retProtocolFee == qProtocolFee
                // reserves change: virtualNft decreases by outputAmount
                && uint256(beforeVirtualNft) >= outputAmount
                && uint256(beforeVirtualNft) - outputAmount == uint256(afterVirtualNft)
                // virtualBase increases by netInput - fee - protocolFee (note netInput already includes those in contract semantics)
                && uint256(afterVirtualBase) >= uint256(beforeVirtualBase)
