contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // The test drives c.buy and asserts a general relation: if buy succeeds (no revert)
    // then virtualNftReserves decreases by the sum of tokenWeights and price() strictly increases.
    // We observe virtualNftReserves and price() via public getters.

    function run(uint256[] calldata tokenIds, uint256[] calldata tokenWeights, bytes32[] calldata proofNodes, bool[] calldata proofFlags, uint256 ethAmount) public payable {
        // require enough balance to forward ETH if needed
        require(address(this).balance >= ethAmount, "insufficient test balance");

        // read pre-state
        uint256 beforeVirtualNft = c.virtualNftReserves();
        uint256 beforePrice = c.price();

        // build MerkleMultiProof struct in memory to pass
        C.MerkleMultiProof memory mp;
        mp.proof = proofNodes;
        mp.flags = proofFlags;

        bool reverted = false;
        // perform buy; send ethAmount in case pool uses ETH
        try c.buy{value: ethAmount}(tokenIds, tokenWeights, mp) returns (uint256 netInputAmount, uint256 feeAmount, uint256 protocolFeeAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // compute sum of weights (observable inputs)
        uint256 sumWeights = 0;
        for (uint256 i = 0; i < tokenWeights.length; i++) {
            sumWeights += tokenWeights[i];
        }

        // read post-state
        uint256 afterVirtualNft = c.virtualNftReserves();
        uint256 afterPrice = c.price();

        // General rule asserted: if buy did not revert then virtualNftReserves decreased by exactly sumWeights
        // and price() increased (since virtualBaseTokenReserves increased and virtualNftReserves decreased).
        assert(reverted || (afterVirtualNft + sumWeights == beforeVirtualNft && afterPrice > beforePrice));
    }

    receive() external payable {}
}

